    <text x=\"30\" y=\"14\">coverage</text>
    <text x=\"90\" y=\"14\">{valueText}</text>
  </g>
</svg>
""");
    }

    /// <summary>
    /// Resolves the badge color based on the coverage percentage.
    /// </summary>
    /// <param name="coveragePercentage">Coverage percentage in the 0-100 range.</param>
    /// <returns>Hex color string.</returns>
    private static string ResolveColor(decimal coveragePercentage)
    {
        return coveragePercentage switch
        {
            >= 90m => "#4c1",
            >= 80m => "#97ca00",
            >= 70m => "#dfb317",
            >= 60m => "#fe7d37",
            _ => "#e05d44",
        };
    }
}

using System.Text.Json;

namespace Oocx.TfPlan2Md.CoverageEnforcer;

/// <summary>
/// Updates the coverage history file with the latest measurement.
/// Related feature: docs/features/043-code-coverage-ci/specification.md
/// </summary>
internal sealed class CoverageHistoryWriter
{
    /// <summary>
    /// JSON serializer options for persisting the history document.
    /// </summary>
    private static readonly JsonSerializerOptions SerializerOptions = new()
    {
        WriteIndented = true,
    };

    /// <summary>
    /// Appends or updates the history file with the latest coverage entry.
    /// </summary>
    /// <param name="historyPath">Path to the history JSON file.</param>
    /// <param name="entry">Coverage history entry to store.</param>
    internal void UpdateHistory(string historyPath, CoverageHistoryEntry entry)
    {
        if (string.IsNullOrWhiteSpace(historyPath))
        {
            throw new InvalidDataException("History file path must be provided.");
        }

        var document = LoadDocument(historyPath);
        var existing = document.Entries.FirstOrDefault(item => string.Equals(item.CommitSha, entry.CommitSha, StringComparison.OrdinalIgnoreCase));
        if (existing is not null)
        {
            document.Entries.Remove(existing);
        }

        document.Entries.Add(entry);
        SaveDocument(historyPath, document);
    }

    /// <summary>
    /// Loads the existing history document or returns an empty document.
    /// </summary>
    /// <param name="historyPath">Path to the history JSON file.</param>
    /// <returns>Loaded coverage history document.</returns>
    private static CoverageHistoryDocument LoadDocument(string historyPath)
    {
        if (!File.Exists(historyPath))
        {
            return new CoverageHistoryDocument();
        }

        var content = File.ReadAllText(historyPath);
        if (string.IsNullOrWhiteSpace(content))
        {
            return new CoverageHistoryDocument();
        }

        return JsonSerializer.Deserialize<CoverageHistoryDocument>(content, SerializerOptions)
            ?? new CoverageHistoryDocument();
    }

    /// <summary>
    /// Persists the coverage history document to disk.
    /// </summary>
    /// <param name="historyPath">Path to the history JSON file.</param>
    /// <param name="document">Document to serialize.</param>
    private static void SaveDocument(string historyPath, CoverageHistoryDocument document)
    {
        var directory = Path.GetDirectoryName(historyPath);
        if (!string.IsNullOrWhiteSpace(directory))
        {
            Directory.CreateDirectory(directory);
        }

        var json = JsonSerializer.Serialize(document, SerializerOptions);
        File.WriteAllText(historyPath, json);
    }
}

using System.Globalization;

namespace Oocx.TfPlan2Md.CoverageEnforcer;

/// <summary>
/// Parses command line arguments for the coverage enforcer tool.
/// Related feature: docs/features/043-code-coverage-ci/specification.md
/// </summary>
internal sealed class CommandLineOptions
{
    /// <summary>
    /// Initializes a new instance of the <see cref="CommandLineOptions"/> class.
    /// </summary>
    /// <param name="reportPath">Path to the Cobertura report.</param>
    /// <param name="lineThreshold">Line coverage threshold percentage.</param>
    /// <param name="branchThreshold">Branch coverage threshold percentage.</param>
    private CommandLineOptions(
        string reportPath,
        decimal lineThreshold,
        decimal branchThreshold,
        string? summaryOutputPath,
        Uri? reportLink,
        bool overrideActive,
        string? badgeOutputPath,
        string? historyOutputPath,
        string? commitSha,
        DateTimeOffset? timestamp)
    {
        ReportPath = reportPath;
        LineThreshold = lineThreshold;
        BranchThreshold = branchThreshold;
        SummaryOutputPath = summaryOutputPath;
        ReportLink = reportLink;
        OverrideActive = overrideActive;
        BadgeOutputPath = badgeOutputPath;
        HistoryOutputPath = historyOutputPath;
        CommitSha = commitSha;
        Timestamp = timestamp;
    }

    /// <summary>
    /// Gets the Cobertura report path.
    /// </summary>
    internal string ReportPath { get; }

    /// <summary>
    /// Gets the configured line coverage threshold percentage.
    /// </summary>
    internal decimal LineThreshold { get; }

    /// <summary>
    /// Gets the configured branch coverage threshold percentage.
    /// </summary>
    internal decimal BranchThreshold { get; }

    /// <summary>
    /// Gets the optional path for writing the markdown summary.
    /// </summary>
    internal string? SummaryOutputPath { get; }

    /// <summary>
    /// Gets the optional link to the detailed coverage report.
    /// </summary>
    internal Uri? ReportLink { get; }

    /// <summary>
    /// Gets a value indicating whether coverage enforcement is overridden.
    /// </summary>
    internal bool OverrideActive { get; }

    /// <summary>
    /// Gets the optional path for writing the badge SVG.
    /// </summary>
    internal string? BadgeOutputPath { get; }

    /// <summary>
    /// Gets the optional path for writing the coverage history JSON.
    /// </summary>
    internal string? HistoryOutputPath { get; }

    /// <summary>
    /// Gets the commit SHA used for history tracking.
    /// </summary>
    internal string? CommitSha { get; }

    /// <summary>
    /// Gets the timestamp to store in history entries.
    /// </summary>
    internal DateTimeOffset? Timestamp { get; }

    /// <summary>
    /// Parses command line arguments and environment variables into options.
    /// </summary>
    /// <param name="args">Command line arguments.</param>
    /// <returns>Parsed command line options.</returns>
    /// <exception cref="InvalidDataException">Thrown when required arguments are missing or invalid.</exception>
    internal static CommandLineOptions Parse(string[] args)
    {
        var reportPath = GetArgumentValue(args, "--report") ?? GetArgumentValue(args, "-r");
        if (string.IsNullOrWhiteSpace(reportPath))
        {
            throw new InvalidDataException("Cobertura report path is required. Use --report <path>.");
        }

        var lineThreshold = GetDecimalArgument(args, "--line-threshold")
            ?? GetDecimalEnvironment("COVERAGE_LINE_THRESHOLD")
            ?? throw new InvalidDataException("Line coverage threshold is required. Use --line-threshold or COVERAGE_LINE_THRESHOLD.");

        var branchThreshold = GetDecimalArgument(args, "--branch-threshold")
            ?? GetDecimalEnvironment("COVERAGE_BRANCH_THRESHOLD")
            ?? throw new InvalidDataException("Branch coverage threshold is required. Use --branch-threshold or COVERAGE_BRANCH_THRESHOLD.");

        var summaryOutputPath = GetArgumentValue(args, "--summary-output");
        var reportLink = GetUriArgument(args, "--report-link");
        var overrideActive = GetBooleanArgument(args, "--override-active") ?? false;
        var badgeOutputPath = GetArgumentValue(args, "--badge-output");
        var historyOutputPath = GetArgumentValue(args, "--history-output");
        var commitSha = GetArgumentValue(args, "--commit-sha");
        var timestamp = GetTimestampArgument(args, "--timestamp");

        return new CommandLineOptions(
            reportPath,
            lineThreshold,
            branchThreshold,
            summaryOutputPath,
            reportLink,
            overrideActive,
            badgeOutputPath,
            historyOutputPath,
            commitSha,
            timestamp);
    }

    /// <summary>
    /// Retrieves a string argument value from the command line, supporting --key=value and --key value formats.
    /// </summary>
    /// <param name="args">Command line arguments.</param>
    /// <param name="name">Argument name to search for.</param>
    /// <returns>Argument value or null if not present.</returns>
    private static string? GetArgumentValue(string[] args, string name)
    {
        for (var index = 0; index < args.Length; index += 1)
        {
            var arg = args[index];
            if (arg.Equals(name, StringComparison.OrdinalIgnoreCase))
            {
                return index + 1 < args.Length ? args[index + 1] : null;
            }

            var prefix = name + "=";
            if (arg.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                return arg[prefix.Length..];
            }
        }

        return null;
    }

    /// <summary>
    /// Retrieves a decimal argument value from the command line.
    /// </summary>
    /// <param name="args">Command line arguments.</param>
    /// <param name="name">Argument name to search for.</param>
    /// <returns>Parsed decimal value or null if not present.</returns>
    /// <exception cref="InvalidDataException">Thrown when the value cannot be parsed.</exception>
    private static decimal? GetDecimalArgument(string[] args, string name)
    {
        var value = GetArgumentValue(args, name);
        return value is null ? null : ParseDecimal(value, name);
    }

    /// <summary>
    /// Retrieves a decimal argument value from the environment.
    /// </summary>
    /// <param name="name">Environment variable name.</param>
    /// <returns>Parsed decimal value or null if not present.</returns>
    /// <exception cref="InvalidDataException">Thrown when the value cannot be parsed.</exception>
    private static decimal? GetDecimalEnvironment(string name)
    {
        var value = Environment.GetEnvironmentVariable(name);
        return string.IsNullOrWhiteSpace(value) ? null : ParseDecimal(value, name);
    }

    /// <summary>
    /// Parses a decimal using invariant culture and throws when invalid.
    /// </summary>
    /// <param name="value">Value to parse.</param>
    /// <param name="source">Source label for error messages.</param>
    /// <returns>Parsed decimal value.</returns>
    /// <exception cref="InvalidDataException">Thrown when parsing fails.</exception>
    private static decimal ParseDecimal(string value, string source)
    {
        if (!decimal.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed))
        {
            throw new InvalidDataException($"Invalid decimal value '{value}' for {source}.");
        }

        return parsed;
    }

    /// <summary>
    /// Parses a URI argument value from the command line.
    /// </summary>
    /// <param name="args">Command line arguments.</param>
    /// <param name="name">Argument name to search for.</param>
    /// <returns>Parsed URI or null if not present.</returns>
    /// <exception cref="InvalidDataException">Thrown when the URI cannot be parsed.</exception>
    private static Uri? GetUriArgument(string[] args, string name)
    {
        var value = GetArgumentValue(args, name);
        if (string.IsNullOrWhiteSpace(value))
        {
            return null;
        }

        if (!Uri.TryCreate(value, UriKind.Absolute, out var uri))
        {
            throw new InvalidDataException($"Invalid URI value '{value}' for {name}.");
        }

        return uri;
    }

    /// <summary>
    /// Parses a boolean argument value from the command line.
    /// </summary>
    /// <param name="args">Command line arguments.</param>
    /// <param name="name">Argument name to search for.</param>
    /// <returns>Parsed boolean value or null if not present.</returns>
    /// <exception cref="InvalidDataException">Thrown when the value cannot be parsed.</exception>
    private static bool? GetBooleanArgument(string[] args, string name)
    {
        var value = GetArgumentValue(args, name);
        if (string.IsNullOrWhiteSpace(value))
        {
            return null;
        }

        if (!bool.TryParse(value, out var parsed))
        {
            throw new InvalidDataException($"Invalid boolean value '{value}' for {name}.");
        }

        return parsed;
    }

    /// <summary>
    /// Parses a timestamp argument value from the command line.
    /// </summary>
    /// <param name="args">Command line arguments.</param>
    /// <param name="name">Argument name to search for.</param>
    /// <returns>Parsed timestamp or null if not present.</returns>
    /// <exception cref="InvalidDataException">Thrown when the timestamp cannot be parsed.</exception>
    private static DateTimeOffset? GetTimestampArgument(string[] args, string name)
    {
        var value = GetArgumentValue(args, name);
        if (string.IsNullOrWhiteSpace(value))
        {
            return null;
        }

        if (!DateTimeOffset.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out var parsed))
        {
            throw new InvalidDataException($"Invalid timestamp value '{value}' for {name}.");
        }

        return parsed.ToUniversalTime();
    }
}

using Oocx.TfPlan2Md.CoverageEnforcer;

try
{
    var options = CommandLineOptions.Parse(args);
    var parser = new CoberturaCoverageParser();
    var metrics = parser.Parse(options.ReportPath);
    var thresholds = new CoverageThresholds(options.LineThreshold, options.BranchThreshold);
    var evaluator = new CoverageThresholdEvaluator();
    var evaluation = evaluator.Evaluate(metrics, thresholds);

    if (!string.IsNullOrWhiteSpace(options.SummaryOutputPath))
    {
        var summaryBuilder = new CoverageSummaryBuilder();
        var summary = summaryBuilder.BuildMarkdown(evaluation, options.ReportLink, options.OverrideActive);
        File.WriteAllText(options.SummaryOutputPath, summary);
    }

    if (!string.IsNullOrWhiteSpace(options.BadgeOutputPath))
    {
        var badgeGenerator = new CoverageBadgeGenerator();
        var badgeSvg = badgeGenerator.GenerateSvg(metrics.LinePercentage);
        File.WriteAllText(options.BadgeOutputPath, badgeSvg);
    }

    if (!string.IsNullOrWhiteSpace(options.HistoryOutputPath))
    {
        if (string.IsNullOrWhiteSpace(options.CommitSha))
        {
            throw new InvalidDataException("Commit SHA is required when updating coverage history.");
        }

        var historyWriter = new CoverageHistoryWriter();
        var timestamp = options.Timestamp ?? DateTimeOffset.UtcNow;
        var entry = new CoverageHistoryEntry(timestamp, options.CommitSha, metrics.LinePercentage, metrics.BranchPercentage);
        historyWriter.UpdateHistory(options.HistoryOutputPath, entry);
    }

    Console.WriteLine("Coverage summary:");
    Console.WriteLine($"  Line:   {metrics.LinePercentage:0.00}% (threshold {thresholds.LineThreshold:0.00}%) {(evaluation.LinePass ? "PASS" : "FAIL")}");
    Console.WriteLine($"  Branch: {metrics.BranchPercentage:0.00}% (threshold {thresholds.BranchThreshold:0.00}%) {(evaluation.BranchPass ? "PASS" : "FAIL")}");

    if (!evaluation.IsPassing)
    {
        if (options.OverrideActive)
        {
            Console.WriteLine("Coverage override active; bypassing enforcement failure.");
            return 0;
        }

        Console.Error.WriteLine("Coverage thresholds not met.");
        return 1;
    }

    Console.WriteLine("Coverage thresholds met.");
    return 0;
}
catch (Exception exception)
{
    Console.Error.WriteLine($"Coverage enforcement failed: {exception.Message}");
    return 2;
}

using System;
